class Calculator:
    def __init__(self):
        self.pos = 0
        self.current_char = None
        self.expr = ""

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        """Advance the `pos` pointer and update `current_char`."""
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        """Skip any whitespace characters in the expression."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        """Return a floating point number after consuming the characters."""
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def factor(self):
        """Parse a factor: either a number or a parenthesis expression."""
        if self.current_char == '(':
            self.advance()
            result = self.expr()
            self.advance()  # Skip '}'
            return result
        else:
            return self.number()

    def term(self):
        """Parse terms including multiplication and division."""
        result = self.factor()
        while self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.advance()
                result *= self.factor()
            elif self.current_char == '/':
                self.advance()
                divisor = self.factor()
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                result /= divisor
        return result

    def expr(self):
        """Parse expressions, including addition and subtraction."""
        result = self.term()
        while self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.advance()
                result += self.term()
            elif self.current_char == '-':
                self.advance()
                result -= self.term()
        return result

def evaluate(expr: str) -> float:
    """
    Evaluate the given arithmetic expression respecting operator precedence
    by implementing a simple recursive descent parser.
    """
    calculator = Calculator()
    calculator.expr = expr
    calculator.current_char = expr[0]
    result = calculator.expr()
    return result

class Parser:
    def __init__(self, expression: str):
        self.expression = expression.replace(" ", "")
        self.pos = 0
        self.current_char = self.expression[self.pos] if self.expression else None

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expression):
            self.current_char = self.expression[self.pos]
        else:
            self.current_char = None

    def parse_number(self):
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def parse_parentheses(self):
        self.advance()  # skip '('
        result = self.expr()
        self.advance()  # skip ')'
        return result

    def factor(self):
        if self.current_char == '(':
            return self.parse_parentheses()
        elif self.current_char.isdigit() or (self.current_char == '-' and (self.pos + 1 < len(self.expression) and self.expression[self.pos + 1].isdigit())):
            return self.parse_number()
        else:
            self.error()

    def term(self):
        result = self.factor()
        while (self.current_char is not None) and (self.current_char in '*/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while (self.current_char is not None) and (self.current_char in '+-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.term()
            elif op == '-':
                result -= self.term()
        return result


def evaluate(expr: str) -> float:
    """Evaluates arithmetic expressions using a recursive descent parser."""
    parser = Parser(expr)
    return parser.expr()

