class TokenType:
    NUMBER = 'NUMBER'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    MULTIPLY = 'MULTIPLY'
    DIVIDE = 'DIVIDE'
    LPAREN = 'LPAREN'
    RPAREN = 'RPAREN'
    EOF = 'EOF'


class Token:
    def __init__(self, type_, value):
        self.type = type_
        self.value = value


class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos]

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return Token(TokenType.NUMBER, float(num_str))

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS, '+')
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS, '-')
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY, '*')
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE, '/')
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN, '(')
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN, ')')
            self.error()

        return Token(TokenType.EOF, None)


class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid syntax')

    def eat(self, token_type):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return token.value
        elif token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

    def term(self):
        result = self.factor()
        while self.current_token.type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token
            if token.type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result *= self.factor()
            elif token.type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()
        return result


def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using a combination of lexical analysis (tokenization) 
    and a recursive descent parsing technique to respect operator precedence and parentheses.
    """
    lexer = Lexer(expr)
    parser = Parser(lexer)
    return parser.expr()

class Evaluator:
    def __init__(self, expr):
        self.expr = expr
        self.pos = 0
        self.current_char = self.expr[self.pos]

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def eat(self, char):
        if self.current_char == char:
            self.advance()
        else:
            self.error()

    def parse_number(self):
        number = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            number += self.current_char
            self.advance()
        return float(number)

    def parse_parentheses(self):
        self.eat('(')
        result = self.parse_expression()
        self.eat(')')
        return result

    def parse_factor(self):
        if self.current_char == '(':
            return self.parse_parentheses()
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.parse_number()
        self.error()

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.eat('*')
                result *= self.parse_factor()
            elif self.current_char == '/':
                self.eat('/')
                result /= self.parse_factor()
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.eat('+')
                result += self.parse_term()
            elif self.current_char == '-':
                self.eat('-')
                result -= self.parse_term()
        return result

def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression with +, -, *, /, and parentheses using a recursive descent parser.
    """
    evaluator = Evaluator(expr.replace(' ', ''))
    return evaluator.parse_expression()
